sys_script_include.script:
var FieldUpdater = Class.create();
FieldUpdater.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    updateField: function() {
        var sysId = this.getParameter('sysparm_sys_id');
        var fieldName = this.getParameter('sysparm_field_name');
        var fieldValue = this.getParameter('sysparm_field_value');

        var gr = new GlideRecord('sc_req_item');
        if (gr.get(sysId)) {
            gr.setValue(fieldName, fieldValue);
            gr.update();
            return "success";
        }
        return "failed";
    },
    type: 'FieldUpdater'
});
